var s={className:"RandomNumberBlock",emit(n,d,t,r,o){let e=o.resolve(n,"seed",t,r);if(e.type==="f32"||e.type==="mat4f"||e.type==="texture2d"||e.type==="textureCube")throw new Error(`NodeMaterial: RandomNumberBlock requires a vector seed so Babylon.js getRand(seed.xy) can be emitted; got ${e.type}`);return r[t].helpers.set("nme_getRand","fn nme_getRand(seed: vec2<f32>) -> f32 { return fract(sin(dot(seed.xy, vec2<f32>(12.9898, 78.233))) * 43758.5453); }"),{expr:`nme_getRand((${e.expr}).xy)`,type:"f32"}}};export{s as emitter};
